    } finally {
      this.saving = false;
    }
  }

  private async read(sheet: string): Promise<void> {
    try {
      const all = await this.service.list(sheet);
      if (this.session.sheetId() === sheet) this.holidays.set(all);
    } catch {
      // The holidays could not be read; they show as none.
    }
  }
}
